package org.slavicmyths.client;
import java.util.*;import java.lang.reflect.*;import java.nio.file.*;
import com.mojang.blaze3d.vertex.*;import net.minecraft.client.model.geom.ModelPart;
import org.joml.*;import org.slavicmyths.pesigolovtsy.*;import org.slavicmyths.pesigolovtsy.DogheadRules.*;
/** Actual clock and native pose checks; never presented as a Minecraft gameplay test. */
public final class DogheadChecks {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static Field children,cubes,polygons;
 static Map<String,Matrix4f> matrices(ModelPart p,Matrix4f parent,String name)throws Exception{var own=new Matrix4f(parent).translate(p.x,p.y,p.z).rotateZYX(p.zRot,p.yRot,p.xRot).scale(p.xScale,p.yScale,p.zScale);var result=new LinkedHashMap<String,Matrix4f>();result.put(name,own);for(var e:((Map<String,ModelPart>)children.get(p)).entrySet())result.putAll(matrices(e.getValue(),own,e.getKey()));return result;}
 static Vector3f origin(Map<String,Matrix4f> m,String name){return m.get(name).transformPosition(new Vector3f());}
 static void export(ModelPart p,PoseStack stack,String name,List<Map<String,Object>> result)throws Exception{if(!p.visible)return;stack.pushPose();p.translateAndRotate(stack);for(var cube:(List<?>)cubes.get(p)){var faces=new ArrayList<List<float[]>>();for(var face:(Object[])polygons.get(cube))if(face!=null){var vf=face.getClass().getDeclaredField("vertices");vf.setAccessible(true);var verts=new ArrayList<float[]>();for(var v:(Object[])vf.get(face)){var pos=v.getClass().getDeclaredField("pos");pos.setAccessible(true);var u=v.getClass().getDeclaredField("u");u.setAccessible(true);var vv=v.getClass().getDeclaredField("v");vv.setAccessible(true);var xyz=stack.last().pose().transformPosition(new Vector3f((Vector3f)pos.get(v)).div(16));check(u.getFloat(v)>=0&&u.getFloat(v)<=1&&vv.getFloat(v)>=0&&vv.getFloat(v)<=1,"atlas bounds");verts.add(new float[]{xyz.x*16,xyz.y*16,xyz.z*16,u.getFloat(v),vv.getFloat(v)});}faces.add(verts);}result.add(Map.of("part",name,"faces",faces));}for(var e:((Map<String,ModelPart>)children.get(p)).entrySet())export(e.getValue(),stack,name+"/"+e.getKey(),result);stack.popPose();}
 public static void main(String[] args)throws Exception{
  for(var clip:Clip.values()){var c=new Clock();c.begin(clip);int events=0;for(int i=1;i<=clip.duration+20;i++){boolean fired=c.tick();if(fired){events++;check(i==clip.marker,"exact marker "+clip);}}check(events==(clip.marker>0?1:0),"once-only event "+clip);c.begin(Clip.READY);for(int i=0;i<40;i++)check(!c.tick(),"aborted marker stays quiet");}
  for(int t=0;t<38;t++){check(DogheadRules.interrupts(Clip.CHOP,t,4)==(t<17),"4 HP commit boundary");check(!DogheadRules.interrupts(Clip.CHOP,t,3.99F),"low damage never cancels axe");}
  check(!DogheadRules.night(11999)&&DogheadRules.night(12000)&&DogheadRules.night(23499)&&!DogheadRules.night(23500),"night boundaries");
  children=ModelPart.class.getDeclaredField("children");cubes=ModelPart.class.getDeclaredField("cubes");polygons=ModelPart.Cube.class.getDeclaredField("polygons");for(var f:List.of(children,cubes,polygons))f.setAccessible(true);
  var model=new DogheadClient.Model();var mesh=new LinkedHashMap<String,List<Map<String,Object>>>();
  for(var role:Role.values()){
   var clips=role==Role.HUNTER?List.of(Clip.READY,Clip.THRUST,Clip.SWEEP,Clip.HUNTER_DEATH):role==Role.LEADER?List.of(Clip.READY,Clip.CHOP,Clip.CLEAVE,Clip.HOWL,Clip.LEADER_DEATH):List.of(Clip.READY,Clip.BOW,Clip.BOW_EQUIP,Clip.KNIFE_SWAP,Clip.KNIFE,Clip.SCOUT_DEATH);
   for(var clip:clips)for(float t=0;t<=java.lang.Math.max(1,clip.duration);t+=.25F){boolean bow=role==Role.SCOUT&&(clip==Clip.BOW||clip==Clip.BOW_EQUIP||clip==Clip.READY);model.pose(role,clip,t,0,0,20,0,0,bow,true,false);var rig=model.rigs.get(role);var m=matrices(rig.root(),new Matrix4f(),"root");if(role!=Role.SCOUT||bow){String main=role==Role.SCOUT?"L":"R",support=main.equals("L")?"R":"L";float a=origin(m,"palm_"+main+"_socket").distance(origin(m,"weapon_hand_socket")),b=origin(m,"palm_"+support+"_socket").distance(origin(m,"weapon_secondary_socket"));check(a<=1&&b<=1,"grip "+role+" "+clip+" t="+t+" main="+a+" support="+b);}
    if(role==Role.SCOUT&&clip==Clip.BOW&&t==22){var world=new Matrix4f().rotateY((float)java.lang.Math.PI).scale(-1F/16,-1F/16,1F/16).translate(0,-24,0).mul(m.get("weapon_root"));var p=world.transformPosition(new Vector3f());var expected=DogheadPose.nock(role,clip,t,0);check(p.distance(new Vector3f((float)expected.x,(float)expected.y,(float)expected.z))<.015,"server arrow matches posed nock");check(!model.n("nocked_arrow").visible,"arrow disappears at release");}
   }
   for(var clip:clips){float t=clip.marker>0?clip.marker:clip.death()?clip.duration*.7F:0;model.pose(role,clip,t,0,0,20,0,0,role==Role.SCOUT&&clip!=Clip.KNIFE&&clip!=Clip.KNIFE_SWAP,true,false);var output=new ArrayList<Map<String,Object>>();export(model.rigs.get(role).root(),new PoseStack(),"root",output);mesh.put(role+"_"+clip,output);}
   Clip attack=role==Role.HUNTER?Clip.THRUST:role==Role.LEADER?Clip.CHOP:Clip.KNIFE;model.pose(role,attack,attack.marker,0,0,20,0,0,false,true,false);var contact=matrices(model.rigs.get(role).root(),new Matrix4f(),"root");var tip=origin(contact,role==Role.SCOUT?"knife_tip":"weapon_tip");float reach=-tip.z/16;check(reach>=(role==Role.HUNTER?2.0F:role==Role.LEADER?1.6F:1.2F),"physical forward contact "+role+" reach="+reach);check(tip.y>0&&tip.y<24,"contact within standing victim height "+role+" y="+tip.y);
   for(float phase=0;phase<1;phase+=.05F){model.pose(role,Clip.READY,0,phase,1,20,0,0,false,true,true);var m=matrices(model.rigs.get(role).root(),new Matrix4f(),"root");String planted=java.lang.Math.sin(phase*java.lang.Math.PI*2)>0?"R":"L";var foot=m.get("foot_"+planted).transformPosition(new Vector3f(0,1.4F,0));check(java.lang.Math.abs(foot.y-24)<1,"planted foot ground "+role+" y="+foot.y);}
  }
  Files.writeString(Path.of("work/pesigolovtsy/meshes.json"),new com.google.gson.Gson().toJson(mesh));System.out.println("DOGHEAD OFFLINE PASS "+checks+" assertions; no game launch.");
 }
}
